require_once __DIR__.'/../includes/functions.php';admin_required();$id=(int)($_GET['id']??0);$message='';$q=db()->prepare('SELECT * FROM invitations WHERE id=?');$q->execute([$id]);$invitation=$q->fetch();if(!$invitation){http_response_code(404);exit('Invitation tidak ditemukan.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo=db();$pdo->exec('INSERT IGNORE INTO gallery(invitation_id) VALUES('.$id.')');$galleryId=(int)$pdo->query('SELECT id FROM gallery WHERE invitation_id='.$id)->fetchColumn();if(isset($_FILES['image'])&&$_FILES['image']['error']===UPLOAD_ERR_OK){$file=$_FILES['image'];if($file['size']>5*1024*1024)throw new RuntimeException('Ukuran maksimal 5MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Format harus JPG, PNG, atau WEBP.');$dir=__DIR__.'/../uploads/gallery';if(!is_dir($dir))mkdir($dir,0750,true);$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Upload gagal.');$path='uploads/gallery/'.$name;$q=$pdo->prepare('INSERT INTO gallery_items(gallery_id,type,path,caption) VALUES(?,"image",?,?)');$q->execute([$galleryId,$path,clean_guest($_POST['caption']??'')]);$message='Foto berhasil diunggah.';}}catch(Throwable $e){$message=$e->getMessage();}}$items=[];try{$q=db()->prepare('SELECT * FROM gallery_items WHERE gallery_id=(SELECT id FROM gallery WHERE invitation_id=?) ORDER BY sort_order,id');$q->execute([$id]);$items=$q->fetchAll();}catch(Throwable){}$page_title='Gallery';require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><header class="admin-header"><span class="eyebrow">MEDIA</span><h1>Gallery invitation</h1></header><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="form-card"><?=csrf_field()?><label>Foto<input required type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Caption<input name="caption" maxlength="255"></label><button class="button">Upload Foto</button></form><section class="table-wrap"><table><thead><tr><th>Preview</th><th>Caption</th><th>Path</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><img loading="lazy" width="100" src="/<?=e($item['path'])?>" alt="<?=e($item['caption'])?>"></td><td><?=e($item['caption'])?></td><td><?=e($item['path'])?></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/includes/footer.php';?>
